using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// ADDN PSDF (a particle system define) is a Reflection object: exact bytes plus FormLinks (none in Starfield.esm).
// A whole record from Starfield.esm, both readers, written back byte for byte.
public class AddonNodeReflectionTests
{
    private static void WritesBack(IStarfieldMajorRecordGetter rec, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => rec.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // spaceMine_Light (255EB7:Starfield.esm)
    private const string SpaceMineLightHex = "";

    [Fact]
    public void SpaceMineLight()
    {
        foreach (var rec in ReadBoth<IAddonNodeGetter>(Record("ADDN", Hex(SpaceMineLightHex)), f => AddonNode.CreateFromBinary(f), (s, p) => AddonNodeBinaryOverlay.AddonNodeFactory(s, p)))
        {
            rec.Reflection.ShouldHaveFormIds();
            rec.Reflection!.Data.Length.ShouldBe(1247);
            rec.Reflection.RootObject().Class.Name.ShouldBe("ParticleSystemDefine");
            WritesBack(rec, SpaceMineLightHex);
        }
    }

}
